// Public demo extension (ADR-0056): keeps the loader registered as a MAIN-world content script at
// document_start on the site's origins while the extension is on. The loader itself (loader.js) is
// generated by tools/extension/build.ts from packages/loader, the same code the demo browser runs.
const api = globalThis.browser ?? globalThis.chrome
const ID = 'vg-loader'
const MATCHES = __MATCHES__

async function enabled() {
	const v = await api.storage.local.get('enabled')
	return v.enabled !== false
}

async function sync() {
	const on = await enabled()
	const have = (await api.scripting.getRegisteredContentScripts({ ids: [ID] })).length > 0
	if (on && !have) await api.scripting.registerContentScripts([{ id: ID, matches: MATCHES, js: ['loader.js'], runAt: 'document_start', world: 'MAIN', allFrames: false }])
	if (!on && have) await api.scripting.unregisterContentScripts({ ids: [ID] })
	await api.action.setBadgeText({ text: on ? '' : 'off' })
}

api.runtime.onInstalled.addListener(() => void sync())
api.runtime.onStartup.addListener(() => void sync())
api.storage.onChanged.addListener((changes, area) => area === 'local' && 'enabled' in changes && void sync())
void sync()
